import { test, expect } from './fixtures';

test('settings compact mode updates status', async ({ page }) => {
  await page.goto('/#/settings');

  await expect(page.getByTestId('settings-title')).toBeVisible();

  const compactCheckbox = page.getByTestId('settings-compact');
  const status = page.getByTestId('settings-status');

  await expect(status).toBeVisible();
  await expect(status).toHaveText('Compact mode off');

  await compactCheckbox.check();

  await expect(compactCheckbox).toBeChecked();
  await expect(status).toBeVisible();
  await expect(status).toHaveText('Compact mode on');
});

