import { test, expect } from './fixtures';

test('inbox filter narrows the message list', async ({ page }) => {
  await page.goto('/#/inbox');

  await expect(page.getByTestId('inbox-title')).toBeVisible();

  const list = page.getByTestId('inbox-list');
  const items = list.getByRole('listitem');
  await expect(items).toHaveCount(3);

  const filter = page.getByTestId('inbox-filter');
  await filter.fill('order');

  await expect(items).toHaveCount(1);
  await expect(items.first()).toHaveText('Your order shipped');
  await expect(list.getByText('Welcome aboard')).toHaveCount(0);
  await expect(list.getByText('Weekly digest')).toHaveCount(0);

  await filter.fill('');
  await expect(items).toHaveCount(3);
  await expect(list.getByText('Welcome aboard')).toBeVisible();
});

