import { test, expect } from './fixtures';

test('smoke: home page loads and cart route is reachable', async ({ page }) => {
  // Step 1: load the app root
  const response = await page.goto('/#/');
  expect(response, 'document response should exist').not.toBeNull();
  expect(response!.status(), 'document should respond with 2xx').toBeLessThan(400);

  await expect(page).toHaveURL(/#\/$/);

  // Step 2: the main application shell is rendered
  const main = page.locator('main, [role="main"]').first();
  await expect(main).toBeVisible();
  await expect(main).not.toBeEmpty();

  // Step 3: somewhere meaningful — the cart page
  await page.goto('/#/cart');
  await expect(page).toHaveURL(/#\/cart$/);
  await expect(main).toBeVisible();

  // A cart page should expose either its heading or its empty-state copy
  const cartContent = page
    .getByRole('heading', { name: /cart/i })
    .or(page.getByText(/cart is empty|your cart is empty|no items/i))
    .first();
  await expect(cartContent).toBeVisible();

  // Step 4: back to home to confirm routing round-trips cleanly
  await page.goto('/#/');
  await expect(page).toHaveURL(/#\/$/);
  await expect(main).toBeVisible();
});

